-- The shop page as a document (akinaza#400): draft and published, versioned, audited. Generated by shop-page-document-migration.ts; never edit by hand.
CREATE TABLE shop_page_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shop_id uuid NOT NULL REFERENCES shops(id) ON DELETE CASCADE,
  version integer NOT NULL CHECK (version >= 1),
  status text NOT NULL CHECK (status IN ('draft','published','archived')),
  schema integer NOT NULL CHECK (schema >= 1),
  doc jsonb NOT NULL CHECK (jsonb_typeof(doc) = 'object'),
  author_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT shop_page_versions_published CHECK ((status = 'draft') = (published_at IS NULL)),
  UNIQUE (shop_id, version)
);
-- One draft and one published document per shop: the published one IS the page.
CREATE UNIQUE INDEX shop_page_versions_one_draft ON shop_page_versions (shop_id) WHERE status = 'draft';
CREATE UNIQUE INDEX shop_page_versions_one_published ON shop_page_versions (shop_id) WHERE status = 'published';

-- Every existing page becomes the document it already is: the same sections in the same order, a hidden one disabled.
INSERT INTO shop_page_versions (shop_id, version, status, schema, doc, published_at)
SELECT sp.shop_id, 1, 'published', 1,
  jsonb_build_object(
    'schema', 1,
    'preset', (SELECT p.preset FROM (VALUES
    ('salon', '{"id":"salon-vitrine","version":1}'::jsonb),
    ('pets', '{"id":"pets-canal","version":1}'::jsonb),
    ('coaching', '{"id":"coaching-studio","version":1}'::jsonb),
    ('workshop', '{"id":"workshop-etabli","version":1}'::jsonb),
    ('cleaning', '{"id":"cleaning-net","version":1}'::jsonb),
    ('consulting', '{"id":"consulting-bureau","version":1}'::jsonb)
    ) AS p(trade, preset) WHERE p.trade = COALESCE(sp.shop_type, CASE s.business_type WHEN 'pets' THEN 'pets' ELSE 'consulting' END)),
    'sections', jsonb_build_array('{"key":"s_hero","type":"hero","variant":"poster","settings":{"focus":"center"},"blocks":[{"key":"b_open_now","type":"fact","settings":{"kind":"open-now"}},{"key":"b_area","type":"fact","settings":{"kind":"area"}}]}'::jsonb)
      || COALESCE((
        SELECT jsonb_agg(m.doc || CASE WHEN l.visible THEN '{}'::jsonb ELSE '{"disabled":true}'::jsonb END ORDER BY l.ord, m.rank)
        FROM (
          SELECT e.value ->> 'id' AS id, (e.value ->> 'visible')::boolean AS visible, e.ord::numeric AS ord
          FROM jsonb_array_elements(sp.sections) WITH ORDINALITY AS e(value, ord)
          UNION ALL
          -- a list that predates trust reads it right before the gallery (the end without one)
          SELECT 'trust', true, COALESCE((SELECT g.ord FROM jsonb_array_elements(sp.sections) WITH ORDINALITY AS g(value, ord) WHERE g.value ->> 'id' = 'gallery'), 1000000) - 0.5
          WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(sp.sections) AS t(value) WHERE t.value ->> 'id' = 'trust')
        ) AS l
        JOIN (VALUES
    ('services', 0, '{"key":"s_services","type":"services","variant":"cards","settings":{"source":"all","groupBy":"none","columns":1,"aside":"none"}}'::jsonb),
    ('team', 0, '{"key":"s_team","type":"team","variant":"row","settings":{"source":"all"}}'::jsonb),
    ('hours', 0, '{"key":"s_hours","type":"visit","variant":"card","settings":{"showPhone":false}}'::jsonb),
    ('zones', 0, '{"key":"s_zones","type":"visit","variant":"map","settings":{"showPhone":false}}'::jsonb),
    ('trust', 0, '{"key":"s_trust_1","type":"story","variant":"owner","settings":{"body":{}}}'::jsonb),
    ('trust', 1, '{"key":"s_trust_2","type":"policies","variant":"inline","settings":{"show":["cancellation","prices","booking-window"]}}'::jsonb),
    ('gallery', 0, '{"key":"s_gallery","type":"gallery","variant":"grid","settings":{"source":"all","texture":"plaster"}}'::jsonb),
    ('wall', 0, '{"key":"s_wall","type":"gallery","variant":"wall","settings":{"source":"all","texture":"plaster"}}'::jsonb),
    ('reels', 0, '{"key":"s_reels_1","type":"video","variant":"tv","settings":{"cabinet":"cabinet"}}'::jsonb),
    ('reels', 1, '{"key":"s_reels_2","type":"video","variant":"shorts","settings":{"cabinet":"cabinet"}}'::jsonb),
    ('reels', 2, '{"key":"s_reels_3","type":"social","variant":"links","settings":{}}'::jsonb),
    ('announcements', 0, '{"key":"s_announcements","type":"bulletin","variant":"board","settings":{}}'::jsonb),
    ('reviews', 0, '{"key":"s_reviews","type":"reviews","variant":"summary-cards","settings":{"rule":"best","count":3}}'::jsonb)
        ) AS m(id, rank, doc) ON m.id = l.id
      ), '[]'::jsonb)
      || '[{"key":"s_booking_panel","type":"booking","variant":"panel","settings":{"count":4}},{"key":"s_booking_sticky","type":"booking","variant":"sticky","settings":{"count":4}}]'::jsonb
  ),
  now()
FROM shop_page sp
JOIN shops s ON s.id = sp.shop_id;
